	@Test
	void reservationDoesNotHashValues() throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig().setAutoGrow(true));
		try {
			ValueStore.FreshValueSession session = store.startFreshValueSessionIfEmpty();
			Value[] values = {
					new SimpleIRI("urn:reservation:iri") {
						@Override
						public int hashCode() {
							throw new AssertionError("Reservation must not hash RDF values");
						}
					},
					new SimpleLiteral("1.25", XSD.DECIMAL) {
						@Override
						public int hashCode() {
							throw new AssertionError("Reservation must not hash RDF values");
						}
					}
			};
			assertDoesNotThrow(() -> store.reservePreparedValueClosureCapacity(session, values));
		} finally {
			store.close();
		}
	}

