	@Test
	void utf8BoundCoversEveryCodePointAndRootLowercase() {
		for (int codePoint = Character.MIN_CODE_POINT; codePoint <= Character.MAX_CODE_POINT; codePoint++) {
			String text = new String(Character.toChars(codePoint));
			long bound = ValueStore.utf8LengthUpperBound(text);
			assertTrue(text.getBytes(StandardCharsets.UTF_8).length <= bound);
			assertTrue(text.toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8).length <= bound);
		}
		for (String text : List.of("İ".repeat(64), "ΟΣΣ", "I\u0307", "😀\uD800\uDC00\uDC00", "")) {
			assertTrue(text.toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8).length <= ValueStore
					.utf8LengthUpperBound(text));
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void reservationPersistsUtf8AndStorageBoundaryValues(boolean canonicalLanguages) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setAutoGrow(true)
				.setValueDBSize(64L * 1024)
				.setInlineLiterals(false);
		StoreProperties properties = new StoreProperties().setCanonicalLanguageTags(canonicalLanguages
				? StoreProperties.CANONICAL_LANGUAGE_TAGS_LOWERCASE_V1
				: null);
		ValueStore store = new ValueStore(directory, properties, config);
		try {
			SimpleValueFactory factory = SimpleValueFactory.getInstance();
			List<Value> values = new ArrayList<>();
			// Exercise the short-key transition, leaf/overflow transition, and overflow page boundaries with
			// actual byte lengths below the cheap bound, as well as maximum-width BMP and supplementary text.
			int[] lengths = { 0, 1, 5, 6, 15, 16, 17, 670, 671, 2000, 2015, 2016, 2017, 2023,
					4064, 4080, 4081, 4095, 4096, 8190 };
			for (int length : lengths) {
				for (String unit : List.of("a", "界", "😀", "\uD800")) {
					String text = decodedUtf8(unit.repeat(length));
					values.add(factory.createLiteral(text));
					values.add(factory.createBNode("b" + text));
					values.add(factory.createIRI("urn:boundary:", "i" + text));
					values.add(factory.createLiteral(text, factory.createIRI("urn:datatype:", "d" + text)));
				}
			}
			for (int languageLength : new int[] { 21, 22, 63, 64, 127, 128 }) {
				values.add(factory.createLiteral("language-" + languageLength, "EN-" + "İ".repeat(languageLength)));
				values.add(factory.createLiteral("direction-" + languageLength, "A".repeat(languageLength),
						Literal.BaseDirection.RTL));
			}
			Value[] input = values.toArray(Value[]::new);
			ValueStore.FreshValueSession session = store.startFreshValueSessionIfEmpty();
			store.reservePreparedValueClosureCapacity(session, input);
			long reservedGrowth = store.getBulkMapGrowthCount();
			long[] ids = persist(store, session, input);
			assertEquals(reservedGrowth, store.getBulkMapGrowthCount(),
					"the complete input must fit the map reserved before ID assignment");
			store.close();
			store = new ValueStore(directory, properties, config);
			for (int i = 0; i < input.length; i++) {
				Value expected = input[i];
				if (input[i]instanceof Literal literal && literal.getLanguage().isPresent()) {
					String language = literal.getLanguage().get();
					if (canonicalLanguages) {
						language = language.toLowerCase(Locale.ROOT);
					}
					expected = factory.createLiteral(literal.getLabel(), language, literal.getBaseDirection());
					assertEquals(language,
							((Literal) store.getValue(ids[i])).getLanguage().orElseThrow());
				}
				assertEquals(expected, store.getValue(ids[i]));
				assertEquals(ids[i], store.getId(expected));
			}
		} finally {
			store.close();
		}
	}

	@Test
	void sharedDatatypeNamespaceIsReservedOncePerBatch() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setAutoGrow(true)
				.setValueDBSize(64L * 1024)
				.setInlineLiterals(false);
		ValueStore store = new ValueStore(directory, config);
		try {
			SimpleValueFactory factory = SimpleValueFactory.getInstance();
			String namespace = "urn:shared:" + "n".repeat(128 * 1024) + ":";
			Value[] input = new Value[512];
			for (int i = 0; i < input.length; i++) {
				// Equal but nonidentical datatype IRIs exercise lexical dependency deduplication.
				input[i] = factory.createLiteral("value-" + i, factory.createIRI(namespace, "datatype"));
			}
			ValueStore.FreshValueSession session = store.startFreshValueSessionIfEmpty();
			store.reservePreparedValueClosureCapacity(session, input);
			long reservedMapSize = mapSize(store);
			assertTrue(reservedMapSize < (long) namespace.length() * input.length,
					"reservation must not allocate a copy of the shared namespace for every literal");
			long reservedGrowth = store.getBulkMapGrowthCount();
			long[] ids = persist(store, session, input);
			assertEquals(reservedGrowth, store.getBulkMapGrowthCount());
			store.reservePreparedValueClosureCapacity(session, input);
			long repeatedMapSize = mapSize(store);
			store.reservePreparedValueClosureCapacity(session, input);
			assertEquals(repeatedMapSize, mapSize(store),
					"repeated conservative reservations without writes must stabilize");
			for (int i = 0; i < input.length; i++) {
				assertEquals(input[i], store.getValue(ids[i]));
			}
			System.out.println("Shared namespace reservation: mapBytes=" + reservedMapSize
					+ ", repeatedMapBytes=" + repeatedMapSize
					+ ", growthCount=" + reservedGrowth + ", values=" + input.length);
		} finally {
			store.close();
		}
	}

	@Test
	void preparedBatchProvidesSharedNestedTripleClosureWithoutReservationRecursion() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setAutoGrow(true).setValueDBSize(64L * 1024);
		ValueStore store = new ValueStore(directory, config);
		try {
			SimpleValueFactory factory = SimpleValueFactory.getInstance();
			IRI predicate = factory.createIRI("urn:triple:predicate");
			List<GuardedTriple> triples = new ArrayList<>();
			Resource subject = factory.createBNode("shared-leaf");
			Value component = subject;
			for (int depth = 0; depth < 80; depth++) {
				GuardedTriple triple = new GuardedTriple(subject, predicate, component);
				triples.add(triple);
				component = triple;
			}
			PreparedStatementBatch.Builder builder = PreparedStatementBatch.builder(1);
			builder.add(subject, predicate, component, null);
			PreparedStatementBatch batch = builder.build();
			Value[] closure = batch.values();
			assertEquals(triples.size() + 2, closure.length, "each shared component occurs once in the closure");
			for (GuardedTriple triple : triples) {
				triple.rejectInspection = true;
			}
			ValueStore.FreshValueSession session = store.startFreshValueSessionIfEmpty();
			assertDoesNotThrow(() -> store.reservePreparedValueCapacity(session, batch));
			for (GuardedTriple triple : triples) {
				triple.rejectInspection = false;
			}
			long[] ids = persist(store, session, closure);
			for (int i = 2; i < closure.length; i++) {
				TripleTerm decoded = (TripleTerm) store.getValue(ids[i]);
				assertNotEquals(0L, ids[i]);
				assertEquals(ids[1], store.getId(decoded.getPredicate()));
				assertEquals(ids[0], store.getId(decoded.getSubject()));
				assertEquals(ids[i == 2 ? 0 : i - 1], store.getId(decoded.getObject()));
			}
		} finally {
			store.close();
		}
	}

	@Test
	void reservationAcceptsEmptyAndRepeatedValueClosures() throws Exception {
		ValueStore store = new ValueStore(directory, new LmdbStoreConfig().setAutoGrow(true));
		try {
			ValueStore.FreshValueSession session = store.startFreshValueSessionIfEmpty();
			Value value = SimpleValueFactory.getInstance().createLiteral("repeat");
			assertDoesNotThrow(() -> store.reservePreparedValueClosureCapacity(session, new Value[0]));
			assertDoesNotThrow(() -> store.reservePreparedValueClosureCapacity(session,
					new Value[] { null, value, value, null }));
			Value[] input = { value, value };
			long[] ids = persist(store, session, input);
			assertEquals(ids[0], ids[1]);
		} finally {
			store.close();
		}
	}

	private static String decodedUtf8(String text) {
		return new String(text.getBytes(StandardCharsets.UTF_8), StandardCharsets.UTF_8);
	}

	private static long[] persist(ValueStore store, ValueStore.FreshValueSession session, Value[] input)
			throws Exception {
		store.startTransaction(true);
		ValueStore.FreshValueAssignment assignment = store.assignFreshValues(session, input);
		ValueStore.FreshValueEncoder encoder = store.freshValueEncoder(session, assignment);
		ValueStore.PreparedValueBatch prepared;
		while ((prepared = encoder.next(128)) != null) {
			store.persistPreparedValues(prepared);
			prepared.releasePersistenceData();
		}
		store.commit();
		store.commitFreshValueTransaction(session);
		store.publishPreparedValues(assignment.publication());
		return Arrays.copyOf(assignment.ids(), input.length);
	}

	private static long mapSize(ValueStore store) throws Exception {
		try (TxnManager.Txn txn = store.getTxnManager().createReadTxnUntracked(); MemoryStack stack = stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			LmdbUtil.E(mdb_env_info(mdb_txn_env(txn.get()), info));
			return info.me_mapsize();
		}
	}

	private static final class GuardedTriple extends SimpleTripleTerm {
		private final int cachedHash;
		private boolean rejectInspection;

		private GuardedTriple(Resource subject, IRI predicate, Value object) {
			super(subject, predicate, object);
			cachedHash = super.hashCode();
		}

		@Override
		public int hashCode() {
			if (rejectInspection) {
				throw new AssertionError("Reservation must not hash nested triples");
			}
			return cachedHash;
		}

		@Override
		public Resource getSubject() {
			if (rejectInspection) {
				throw new AssertionError("Reservation must not walk flattened triple components");
			}
			return super.getSubject();
		}

		@Override
		public IRI getPredicate() {
			if (rejectInspection) {
				throw new AssertionError("Reservation must not walk flattened triple components");
			}
			return super.getPredicate();
		}

		@Override
		public Value getObject() {
			if (rejectInspection) {
				throw new AssertionError("Reservation must not walk flattened triple components");
			}
			return super.getObject();
		}
	}
